<script lang="ts">
 import {onMount} from 'svelte';
 import QuoteField from './QuoteField.svelte';
 import {pages,activePages,matches,quotesAPI,QuoteError,fieldDefaults,pageValues,type Quote,type Value,type FormPage} from './quote-model';
 let list=$state<Quote[]>([]), quote=$state<Quote|null>(null), pageID=$state('newquote');
 let values=$state<Record<string,Value>>({}), rows=$state<Record<string,Value>[]>([]);
 let errors=$state<Record<string,string>>({}), error=$state(''), notice=$state(''), busy=$state(false), dirty=$state(false), creating=$state(false), loading=$state(true);
 let request=0; let mounted=false;
 const page=$derived(pages.find(p=>p.id===pageID)??pages[0]);
 const journey=$derived(activePages(values));
 const step=$derived(journey.findIndex(p=>p.id===pageID));
 const fields=$derived(page.fields.filter(f=>matches(f.showWhen,values)));
 const groups=$derived([...new Set(fields.map(f=>f.group??'Details'))]);
 const collection=$derived(page.collection&&matches(page.collection.when,values)?page.collection:undefined);
 const eligible=$derived(!!quote&&journey.filter(p=>p.id!=='review').every(p=>quote!.completed.includes(p.id)));
 function leaveOK(){return !dirty||window.confirm('You have unsaved changes. Discard them?');}
 function route(id?:string){history.replaceState(null,'',location.pathname+(id?`#personalhome/quote/${id}`:'#personalhome/newquote'));}
 function install(q:Quote,target=q.current_page){if(!mounted)return;quote=q;values=structuredClone($state.snapshot(q.values));pageID=target;rows=structuredClone($state.snapshot(q.collections[pages.find(p=>p.id===target)?.collection?.key??'']??[]));errors={};error='';dirty=false;creating=false;route(q.id);window.scrollTo({top:0,behavior:'instant'});}
 function showError(e:unknown){error=e instanceof Error?e.message:String(e);errors=e instanceof QuoteError?e.fields:{};notice='';}
 async function load(){const token=++request;loading=true;error='';try{const id=location.hash.match(/^#personalhome\/quote\/([a-f0-9]{24})/)?.[1];if(id){const q=await quotesAPI.get(id);if(token===request)install(q);}else{const items=await quotesAPI.list();if(token===request){list=items;quote=null;creating=false;dirty=false;}}}catch(e){if(token===request)showError(e);}finally{if(token===request)loading=false;}}
 onMount(()=>{mounted=true;void load();const before=(e:BeforeUnloadEvent)=>{if(dirty){e.preventDefault();e.returnValue='';}};const navigation=(e:Event)=>{if(!leaveOK()){e.preventDefault();route(quote?.id);}};const hash=()=>{if(!location.hash.startsWith('#personalhome'))return;if(!leaveOK()){route(quote?.id);return;}void load();};window.addEventListener('beforeunload',before);window.addEventListener('quote-before-leave',navigation);window.addEventListener('hashchange',hash);return()=>{mounted=false;request++;window.removeEventListener('beforeunload',before);window.removeEventListener('quote-before-leave',navigation);window.removeEventListener('hashchange',hash);};});
 function start(){if(!leaveOK())return;quote=null;creating=true;pageID='newquote';values=fieldDefaults(pages.flatMap(p=>p.fields));rows=[];errors={};error='';notice='';dirty=false;route();}
 async function open(q:Quote){if(!leaveOK())return;busy=true;error='';try{install(await quotesAPI.get(q.id));notice='';}catch(e){showError(e);}finally{busy=false;}}
 async function dashboard(){if(!leaveOK())return;dirty=false;route();await load();}
 function change(key:string,value:Value){if(key==='CoverageADwellingInput.Limit'&&typeof value==='number'&&values['DwellingInput.Form']==='HO3'){for(const [dependent,factor] of Object.entries({'CoverageCPersonalPropertyHO3Input.Limit':0.5,'CoverageDLossOfUseInput.Limit':0.2})){if(values[dependent]===null||values[dependent]===undefined||values[dependent]==='')values={...values,[dependent]:Math.round(value*factor)};}if(!values['ReplacementCostDwellingInput.ReplacementCostValue'])values={...values,'ReplacementCostDwellingInput.ReplacementCostValue':value};}values={...values,[key]:value};dirty=true;notice='';errors={...errors,[key]:''};if(key==='DwellingInput.Form'&&value==='HO6')values={...values,'DwellingInput.RoofGeometry':'NA','ReplacementCostDwellingInput.Indicator':false};}
 function updateRow(index:number,key:string,value:Value){rows=rows.map((row,i)=>i===index?{...row,[key]:value}:row);dirty=true;notice='';}
 function addRow(){if(!collection)return;rows=[...rows,fieldDefaults(collection.fields)];dirty=true;notice='';}
 function removeRow(index:number){rows=rows.filter((_,i)=>i!==index);dirty=true;notice='';errors={};}
 function navigate(target:FormPage){if(!quote||!leaveOK())return;install(quote,target.id);notice='';}
 function reachable(target:FormPage){if(!quote)return false;const index=journey.findIndex(p=>p.id===target.id);return journey.slice(0,index).every(p=>quote!.completed.includes(p.id));}
 async function save(advance:boolean){if(busy)return;busy=true;error='';errors={};notice='';try{const saved=quote?await quotesAPI.save(quote,pageID,pageValues(page,values),rows,advance):await quotesAPI.create(pageValues(pages[0],values));install(saved);notice=advance?'Saved. Continue with the next step.':'Draft saved.';}catch(e){showError(e);}finally{busy=false;}}
 async function submit(){if(!quote||busy)return;busy=true;error='';try{const saved=await quotesAPI.submit(quote);install(saved);notice='Application submitted locally. Rating and carrier review are pending.';}catch(e){showError(e);}finally{busy=false;}}
 function copyAddress(){for(const key of ['Address1','Address2','City','State','ZipCode','County'])values={...values,['LocationInput.'+key]:values['AccountInput.'+key]??''};dirty=true;notice='Applicant address copied. Save this page to keep it.';}
 function exportQuote(){if(!quote)return;const url=URL.createObjectURL(new Blob([JSON.stringify(quote,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=quote.number+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 const display=(v:Value|undefined)=>v===true?'Yes':v===false?'No':v===null||v===undefined||v===''?'Not provided':String(v);
</script>

<div class="application">
 <div class="application-header"><div><span class="eyebrow">MANATEE · FLORIDA PERSONAL HOME</span><h1>{quote?quote.number:creating?'Start a new quote':'Your quotes'}</h1><p class="muted">{quote?'Complete your application one step at a time.':'Create, save and resume PersonalHome applications.'}</p></div><div class="header-actions">{#if quote||creating}<button class="btn" disabled={busy} onclick={dashboard}>All quotes</button>{:else}<button class="btn primary" disabled={loading||busy} onclick={start}>Create quote</button>{/if}{#if quote}<span class="status">{quote.status==='ready_for_rating'?'Awaiting rating':'Draft'}</span>{/if}</div></div>
 {#if error}<div class="message error" role="alert"><b>{error}</b>{#if Object.keys(errors).length}<ul>{#each Object.entries(errors).filter(([,v])=>v) as [key,message]}<li>{pages.flatMap(p=>p.fields).find(f=>f.key===key)?.label??key}: {message}</li>{/each}</ul>{/if}{#if !Object.keys(errors).length}<button class="btn sm" disabled={busy} onclick={()=>{if(leaveOK())void load();}}>Reload saved data</button>{/if}</div>{/if}
 {#if notice}<div class="message success" role="status">{notice}</div>{/if}
 {#if loading}<p role="status">Loading saved quotes…</p>
 {:else if !quote&&!creating}
  {#if !list.length&&!error}<section class="empty"><div class="home-icon">⌂</div><h2>Your next home policy starts here</h2><p>Choose a policy form and effective date, then complete applicant, property and coverage details.</p><button class="btn primary" onclick={start}>Create your first quote</button></section>{/if}
  <div class="quote-list">{#each list as item}<button class="quote-card" disabled={busy} onclick={()=>open(item)}><div><b>{item.number}</b><span class="status">{item.status==='ready_for_rating'?'Awaiting rating':'Draft'}</span></div><h3>{[item.values['AccountInput.FirstName'],item.values['AccountInput.LastName']].filter(Boolean).join(' ')||'New applicant'}</h3><p>{item.values['DwellingInput.Form']} · Effective {item.values['PolicyInput.EffectiveDate']}</p><p class="muted">Continue: {pages.find(p=>p.id===item.current_page)?.title}</p><small>Saved {new Date(item.updated_at).toLocaleString()}</small></button>{/each}</div>
 {:else}
  <div class="quote-layout">
   <nav class="quote-nav" aria-label="Quote steps">{#each journey as item,i}<button class:active={pageID===item.id} disabled={busy||!reachable(item)} aria-current={pageID===item.id?'step':undefined} onclick={()=>navigate(item)}><span>{quote?.completed.includes(item.id)?'✓':i+1}</span>{item.title}</button>{/each}</nav>
   <div class="quote-body">
    <section class="form-card"><div class="page-title"><div><span class="eyebrow">STEP {step+1} OF {journey.length}</span><h2>{page.title}</h2></div><span class="save-state">{dirty?'Unsaved changes':quote?'Saved on this computer':'New quote'}</span></div>
     {#if page.notice}<p class="info">{page.notice}</p>{/if}
     {#if pageID==='newquote'}<p class="muted">Start with your product and effective date. A quote number is assigned when you continue.</p>{/if}
     {#if pageID==='dwellinginfo'}<div class="copy-address"><p class="muted">Enter the insured property's address.</p><button class="btn sm" disabled={busy} onclick={copyAddress}>Copy applicant address</button></div>{/if}
     <fieldset disabled={busy}>
      {#each groups as group}<section class="field-group"><h3>{group}</h3><div class="field-grid">{#each fields.filter(f=>(f.group??'Details')===group) as field (pageID+field.key)}<QuoteField {field} id={'quote-'+field.key} value={values[field.key]} context={values} invalid={errors[field.key]} onchange={value=>change(field.key,value)}/>{/each}</div></section>{/each}
      {#if collection}<section class="repeat-section"><div class="repeat-heading"><h3>{collection.label}</h3><button type="button" class="btn sm" disabled={rows.length>=100} onclick={addRow}>+ Add {collection.key==='losses'?'loss':collection.key==='priorInsurance'?'prior policy':collection.key==='coapplicants'?'co-applicant':'interest'}</button></div>{#if errors[collection.key]}<p class="field-error">{errors[collection.key]}</p>{/if}{#if !rows.length}<p class="muted">No entries added.</p>{/if}
       {#each rows as row,i}<article class="repeat-row"><div class="repeat-heading"><b>Entry {i+1}</b><button class="btn sm ghost" onclick={()=>removeRow(i)}>Remove entry {i+1}</button></div><div class="field-grid">{#each collection.fields as field}<QuoteField {field} id={collection.key+'-'+i+'-'+field.key} value={row[field.key]} context={values} invalid={errors[collection.key+'.'+i+'.'+field.key]} onchange={value=>updateRow(i,field.key,value)}/>{/each}</div></article>{/each}
      </section>{/if}
     </fieldset>
     {#if pageID==='summary'||pageID==='review'}
      <div class="rating"><span>Premium</span><strong>Awaiting rating</strong><p>No premium has been calculated. This application does not provide an insurance offer or coverage.</p></div>
      {#if pageID==='review'&&quote?.status==='ready_for_rating'}<div class="message success"><h3>Application captured</h3><p>{quote.number} has been saved and marked ready for rating. A carrier connection is required to obtain a premium and bind coverage.</p><button class="btn" onclick={exportQuote}>Download saved application</button></div>{/if}
      {#each journey.filter(p=>pageID==='review'?!['summary','review'].includes(p.id):['newquote','dwellingcoverage'].includes(p.id)) as section}
       <details class="review-section" open={pageID==='summary'}><summary>{section.title} {#if quote?.completed.includes(section.id)}✓{/if}</summary><dl>{#each section.fields.filter(f=>matches(f.showWhen,values)) as f}<dt>{f.label}</dt><dd>{display(values[f.key]??f.default)}</dd>{/each}</dl>{#if section.collection&&matches(section.collection.when,values)}{#each quote?.collections[section.collection.key]??[] as entry,i}<h4>{section.collection.label} {i+1}</h4><dl>{#each section.collection.fields as f}<dt>{f.label}</dt><dd>{display(entry[f.key])}</dd>{/each}</dl>{/each}{/if}<button class="btn sm" disabled={busy} onclick={()=>navigate(section)}>Edit {section.title.toLowerCase()}</button></details>
      {/each}
     {/if}
     <div class="form-actions">{#if quote&&step>0}<button class="btn" disabled={busy} onclick={()=>navigate(journey[step-1])}>← Back</button>{/if}<span class="spacer"></span>{#if pageID==='review'}<button class="btn primary" disabled={busy||!eligible||quote?.status==='ready_for_rating'} onclick={submit}>{busy?'Submitting…':quote?.status==='ready_for_rating'?'Submitted for rating':'Submit application for rating'}</button>{:else}{#if quote}<button class="btn" disabled={busy} onclick={()=>save(false)}>{busy?'Saving…':'Save draft'}</button>{/if}<button class="btn primary" disabled={busy} onclick={()=>save(true)}>{busy?'Saving…':creating?'Create quote & continue':'Save & continue →'}</button>{/if}</div>
    </section>
    <p class="footer-note">Your quote is stored on this computer. Rating, CLUE, payment processing and policy binding require carrier integrations.</p>
   </div>
  </div>
 {/if}
</div>
<style>
 .application{max-width:1200px;margin:auto}.application-header{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:8px 0 28px}.eyebrow{font-size:11px;font-weight:700;letter-spacing:1px;color:var(--text-muted)}h1{font-size:30px;margin:8px 0}h2{font-size:24px;margin:6px 0 14px}h3{font-size:15px;margin:0 0 16px}p{line-height:1.6}.header-actions{display:flex;gap:12px;align-items:center}.status{font-size:12px;background:var(--accent-soft);color:var(--accent);padding:6px 10px;border-radius:20px;white-space:nowrap}.quote-layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:24px;align-items:start}.quote-nav{display:grid;gap:5px;position:sticky;top:90px}.quote-nav button{border:0;background:none;color:var(--text-muted);display:flex;align-items:center;gap:10px;text-align:left;padding:12px 10px;border-radius:8px;font:inherit;cursor:pointer}.quote-nav button:disabled{opacity:.5;cursor:default}.quote-nav button.active{background:var(--accent-soft);color:var(--accent);opacity:1;font-weight:600}.quote-nav button span{width:24px;height:24px;display:grid;place-items:center;border-radius:50%;background:var(--surface-3);font-size:12px;flex-shrink:0}.quote-nav button.active span{background:var(--accent);color:var(--accent-text)}.form-card{padding:28px;background:var(--surface);border:1px solid var(--border);border-radius:14px;box-shadow:var(--shadow)}.page-title{display:flex;justify-content:space-between;gap:12px}.save-state{font-size:12px;color:var(--text-muted)}.field-group{padding:22px 0;border-top:1px solid var(--border)}.field-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.field-group h3{color:var(--text-muted)}fieldset{border:0;margin:0;padding:0;min-width:0}.form-actions{border-top:1px solid var(--border);padding-top:22px;margin-top:20px;display:flex;gap:10px;align-items:center;flex-wrap:wrap}.spacer{flex:1}.message{padding:16px 20px;border-radius:10px;margin:14px 0;line-height:1.5}.error{background:var(--danger-soft);color:var(--danger)}.success{background:var(--success-soft);color:var(--success)}.info{padding:12px 16px;background:var(--info-soft);color:var(--info);border-radius:8px;font-size:13px}.empty{text-align:center;padding:65px 24px;background:var(--surface);border:1px solid var(--border);border-radius:14px}.home-icon{font-size:56px;color:var(--accent)}.empty p{max-width:490px;margin:16px auto 24px}.quote-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:18px}.quote-card{text-align:left;padding:24px;border:1px solid var(--border);border-radius:12px;background:var(--surface);color:var(--text);cursor:pointer}.quote-card:hover{border-color:var(--accent)}.quote-card>div{display:flex;justify-content:space-between;gap:12px;margin-bottom:20px}.quote-card h3{font-size:18px}.quote-card small{color:var(--text-muted)}.repeat-section{border-top:1px solid var(--border);padding:20px 0}.repeat-heading,.copy-address{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px}.repeat-heading h3{margin:0}.repeat-row{background:var(--surface-2);padding:18px;border-radius:10px;margin:14px 0}.field-error{color:var(--danger)}.rating{display:grid;gap:8px;background:var(--surface-2);padding:22px;border-radius:10px;margin:18px 0}.rating strong{font-size:26px}.rating p{margin:0;color:var(--text-muted)}.review-section{border-top:1px solid var(--border);padding:18px 0}.review-section summary{font-weight:600;cursor:pointer}dl{display:grid;grid-template-columns:1fr 1fr;gap:10px;font-size:13px}dt{color:var(--text-muted)}dd{margin:0;overflow-wrap:anywhere}.footer-note{text-align:center;font-size:12px;color:var(--text-muted)}
 @media(max-width:850px){.quote-layout{grid-template-columns:1fr}.quote-nav{position:static;display:flex;overflow:auto;padding-bottom:8px}.quote-nav button{white-space:nowrap}.form-card{padding:20px}}
 @media(max-width:540px){.field-grid{grid-template-columns:1fr}.application-header{align-items:start;flex-direction:column}.page-title{flex-direction:column}.form-actions .spacer{display:none}.form-actions{justify-content:space-between}.form-actions button{flex:1}.repeat-heading,.copy-address{flex-wrap:wrap}}
</style>
